$ErrorActionPreference='Stop'
param([Parameter(Mandatory)][string]$Number,[Parameter(Mandatory)][string]$Slug,[Parameter(Mandatory)][string]$Title,[Parameter(Mandatory)][string]$Prerequisite)
if($Number -notmatch '^\d{2}$'){throw 'Number must be exactly two digits.'};if($Slug -notmatch '^[a-z0-9]+(?:-[a-z0-9]+)*$'){throw 'Slug must be kebab-case.'};$module="labs/$Number-$Slug";if(Test-Path $module){throw "$module already exists."};New-Item -ItemType Directory -Force "$module/src/main/java","$module/src/test/java"|Out-Null;$template=Get-Content docs/templates/lab-readme.md -Raw;$template=$template.Replace('<Number>',$Number).Replace('<Lesson Title>',$Title).Replace('## Prerequisites',('## Prerequisites'+[Environment]::NewLine+$Prerequisite));Set-Content "$module/README.md" $template -Encoding utf8;$pom="<project xmlns=`"http://maven.apache.org/POM/4.0.0`"><modelVersion>4.0.0</modelVersion><parent><groupId>dev.studyforge</groupId><artifactId>studyforge-curriculum</artifactId><version>1.0.0-SNAPSHOT</version><relativePath>../../pom.xml</relativePath></parent><artifactId>$Slug</artifactId><version>1.0.0-SNAPSHOT</version></project>";Set-Content "$module/pom.xml" $pom -Encoding utf8;$rootPom=Get-Content pom.xml -Raw;$rootPom=$rootPom.Replace('<module>projects/banking-core</module>',"<module>$module</module><module>projects/banking-core</module>");Set-Content pom.xml $rootPom -Encoding utf8;$catalog=Get-Content README.md -Raw;$row="| $Number | $Title | Planned | $Prerequisite | Complete the lesson exercises | $module/README.md |"+[Environment]::NewLine;$catalog=$catalog.Replace('## Projects'+[Environment]::NewLine,$row+'## Projects'+[Environment]::NewLine);Set-Content README.md $catalog -Encoding utf8;& "$PSScriptRoot/validate-curriculum.ps1"
